SELECT public._test_assert(to_regprocedure('public.platform_assign_workspace_member(uuid,uuid,public.workspace_role,text)') IS NOT NULL,'atomic role/profile administration RPC exists');
SELECT public._test_assert(to_regprocedure('public.platform_update_workspace(uuid,text,smallint,uuid)') IS NOT NULL,'atomic metadata/ownership administration RPC exists');
BEGIN;
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';
SELECT public._test_rejected($$SELECT public.platform_assign_workspace_member('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000004','member','invalid')$$,'23514','invalid compound profile update fails atomically');
SELECT public.platform_assign_workspace_member('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000004','admin','strategic');
RESET ROLE;
SELECT public._test_assert((SELECT role='admin' AND member_profile='operational' FROM public.workspace_members WHERE workspace_id='10000000-0000-4000-8000-000000000001' AND user_id='00000000-0000-4000-8000-000000000004'),'compound administration normalizes admin profile and retains role');
UPDATE auth.users SET banned_until=now()+interval '1 day' WHERE id='00000000-0000-4000-8000-000000000007';
SET LOCAL ROLE authenticated;
SELECT public._test_rejected($$SELECT public.platform_update_workspace('10000000-0000-4000-8000-000000000001','Uncommitted',NULL,'00000000-0000-4000-8000-000000000007')$$,'23514','failed ownership transfer rolls back metadata too');
RESET ROLE;
SELECT public._test_assert((SELECT name='Fixture' AND owner_id='00000000-0000-4000-8000-000000000002' FROM public.workspaces WHERE id='10000000-0000-4000-8000-000000000001'),'failed compound transfer preserves previous owner and metadata');
SET LOCAL ROLE authenticated;
SELECT public.platform_update_workspace('10000000-0000-4000-8000-000000000001','Committed',NULL,'00000000-0000-4000-8000-000000000003');
RESET ROLE;
SELECT public._test_assert((SELECT name='Committed' AND owner_id='00000000-0000-4000-8000-000000000003' FROM public.workspaces WHERE id='10000000-0000-4000-8000-000000000001') AND (SELECT role='owner' FROM public.workspace_members WHERE workspace_id='10000000-0000-4000-8000-000000000001' AND user_id='00000000-0000-4000-8000-000000000003'),'compound workspace update synchronizes metadata owner and membership');
ROLLBACK;
